//! On-disk format compatibility: golden table directories under `fixtures/`
//! (see "Formato em disco v1.0" in docs/architecture.md). The `plain_v2`,
//! `ctr_v2`, `wal_v1` and `deleted_v3` fixtures were generated by the code
//! that wrote format v0.x (before authenticated encryption); the current code
//! must read them with identical results. `aead_v3` locks the authenticated
//! format. Regenerate only deliberately: `cargo test -p moosedb-tests
//! gen_fixture -- --ignored`.

use std::path::{Path, PathBuf};

use super::helpers::*;
use moosedb_core::time::MICROS_PER_SEC;
use moosedb_core::{RawOptions, Row, Table};

const KEY: u32 = 7;

fn fixtures() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("fixtures")
}

fn opts(encrypted: bool) -> RawOptions<'static> {
    RawOptions { encryption_key_id: encrypted.then_some(KEY), ..Default::default() }
}

fn copy_dir(from: &Path, to: &Path) {
    std::fs::create_dir_all(to).unwrap();
    for e in std::fs::read_dir(from).unwrap() {
        let e = e.unwrap();
        std::fs::copy(e.path(), to.join(e.file_name())).unwrap();
    }
}

/// 30 rows flushed into a chunk, then 5 rows that stay in the WAL.
fn populate(t: &Table) {
    for i in 0..30 {
        t.write(row(i, if i % 2 == 0 { "srv1" } else { "srv2" }, i as f64)).unwrap();
    }
    t.flush().unwrap();
    for i in 100..105 {
        t.write(row(i, "srv1", i as f64)).unwrap();
    }
    t.sync_wal(true).unwrap();
}

fn rows(secs: impl Iterator<Item = i64>) -> Vec<Row> {
    secs.map(|i| row(i, if i >= 100 || i % 2 == 0 { "srv1" } else { "srv2" }, i as f64)).collect()
}

fn expected(case: &str) -> Vec<Row> {
    match case {
        "wal_v1" => rows((0..30).chain(100..105)),
        "deleted_v3" => rows((10..30).chain(100..105)),
        _ => rows((0..30).chain(100..105)),
    }
}

fn generate(case: &str, encrypted: bool) {
    crate::encryption_tests::install();
    let tmp = tempfile::tempdir().unwrap();
    let path = tmp.path().join("t");
    let t = create_open(&path, opts(encrypted));
    match case {
        "wal_v1" => {
            for i in (0..30).chain(100..105) {
                t.write(row(i, if i >= 100 || i % 2 == 0 { "srv1" } else { "srv2" }, i as f64)).unwrap();
            }
            t.sync_wal(true).unwrap();
        }
        "deleted_v3" => {
            populate(&t);
            let hi = base_ts() + 10 * MICROS_PER_SEC - 1;
            t.delete_range(None, base_ts() - MICROS_PER_SEC, hi, None, true).unwrap();
            t.flush().unwrap(); // the flush records the tombstone in a v3 MANIFEST
        }
        _ => populate(&t),
    }
    drop(t);
    if case == "wal_v1" {
        downgrade_wal_to_v1(&path);
    }
    let out = fixtures().join(case);
    let _ = std::fs::remove_dir_all(&out);
    copy_dir(&path, &out);
}

/// Rewrites the (plain, ROW_COMMIT-only) v2 segments of `dir` in the v1
/// layout: version 1, payload = row without the kind byte, CRC recomputed.
fn downgrade_wal_to_v1(dir: &Path) {
    for e in std::fs::read_dir(dir).unwrap() {
        let p = e.unwrap().path();
        if !p.to_string_lossy().ends_with(".tfl.wal") {
            continue;
        }
        let d = std::fs::read(&p).unwrap();
        if d.len() <= 8 {
            continue;
        }
        let mut out = d[..8].to_vec();
        out[4..6].copy_from_slice(&1u16.to_le_bytes());
        let mut pos = 8;
        while pos < d.len() {
            let len = u32::from_le_bytes(d[pos + 4..pos + 8].try_into().unwrap()) as usize;
            let payload = &d[pos + 8..pos + 8 + len];
            assert_eq!(payload[0], 3, "only ROW_COMMIT entries expected");
            let body = &payload[1..];
            let len_bytes = (body.len() as u32).to_le_bytes();
            let mut h = crc32fast::Hasher::new();
            h.update(&len_bytes);
            h.update(body);
            out.extend_from_slice(&h.finalize().to_le_bytes());
            out.extend_from_slice(&len_bytes);
            out.extend_from_slice(body);
            pos += 8 + len;
        }
        std::fs::write(&p, out).unwrap();
    }
}

#[test]
#[ignore = "writes fixtures with the current format"]
fn gen_fixture_legacy() {
    generate("plain_v2", false);
    generate("ctr_v2", true);
    generate("wal_v1", false);
    generate("deleted_v3", false);
}

#[test]
#[ignore = "writes fixtures with the current format"]
fn gen_fixture_aead() {
    generate("aead_v3", true);
}

fn open_case(case: &str, encrypted: bool) -> (tempfile::TempDir, Table) {
    crate::encryption_tests::install();
    let tmp = tempfile::tempdir().unwrap();
    let path = tmp.path().join("t");
    copy_dir(&fixtures().join(case), &path);
    let t = Table::open(config(&path, opts(encrypted))).unwrap();
    (tmp, t)
}

fn check_case(case: &str, encrypted: bool) -> (tempfile::TempDir, Table) {
    let (tmp, t) = open_case(case, encrypted);
    assert_eq!(sorted(all_rows(&t)), sorted(expected(case)), "{case}");
    assert!(t.check().unwrap().is_empty(), "{case}: CHECK TABLE");
    (tmp, t)
}

fn chunk_versions(t: &Table) -> Vec<u16> {
    t.chunks().unwrap().iter().map(|c| c.header.version).collect()
}

#[test]
fn plain_v2_is_read_unchanged() {
    let (_d, t) = check_case("plain_v2", false);
    assert_eq!(chunk_versions(&t), vec![2]);
}

#[test]
fn wal_v1_is_replayed() {
    check_case("wal_v1", false);
}

#[test]
fn manifest_v3_with_tombstones_is_read() {
    check_case("deleted_v3", false);
}

#[test]
fn unauthenticated_ctr_files_stay_readable_and_compaction_upgrades_them() {
    let (_d, t) = check_case("ctr_v2", true);
    assert_eq!(chunk_versions(&t), vec![2], "legacy CTR chunk");
    assert!(t.chunks().unwrap().iter().all(|c| c.header.is_encrypted()));
    // The bucket holds that single legacy chunk: OPTIMIZE rewrites it anyway.
    assert_eq!(t.compact(i64::MIN, i64::MAX, base_ts()).unwrap().groups, 1);
    assert_eq!(sorted(all_rows(&t)), sorted(expected("ctr_v2")));
    assert!(chunk_versions(&t).iter().all(|&v| v == 3), "{:?}", chunk_versions(&t));
}

#[test]
fn aead_v3_is_read_unchanged() {
    let (_d, t) = check_case("aead_v3", true);
    assert_eq!(chunk_versions(&t), vec![3]);
}

// --- Tampering -------------------------------------------------------------
// The attacker model: bytes are changed on disk and every checksum is
// recomputed, so only the authentication tags can notice.

fn crc(b: &[u8]) -> [u8; 4] {
    crc32fast::hash(b).to_le_bytes()
}

fn fix_chunk_crcs(b: &mut [u8]) {
    let c = crc(&b[..60]);
    b[60..64].copy_from_slice(&c);
    if b[6] & 2 != 0 {
        let c = crc(&b[64..92]);
        b[92..96].copy_from_slice(&c);
    }
    let f = b.len() - 24;
    let c = crc(&b[..f + 16]);
    b[f + 16..f + 20].copy_from_slice(&c);
}

fn chunk_path(dir: &Path) -> PathBuf {
    std::fs::read_dir(dir).unwrap().map(|e| e.unwrap().path()).find(|p| p.extension().is_some_and(|x| x == "tfl")).unwrap()
}

fn wal_path(dir: &Path) -> PathBuf {
    std::fs::read_dir(dir).unwrap().map(|e| e.unwrap().path()).find(|p| p.to_string_lossy().ends_with(".tfl.wal")).unwrap()
}

/// What a client would see: the open error, the scan error, or the rows.
fn outcome(dir: &Path) -> Result<Vec<Row>, moosedb_core::Error> {
    let t = Table::open(config(dir, opts(true)))?;
    let mut s = t.scan(&Default::default(), false)?;
    let mut out = Vec::new();
    while let Some((_, r)) = s.next_row()? {
        out.push(r);
    }
    Ok(out)
}

fn tampered_copy(f: impl FnOnce(&Path)) -> (tempfile::TempDir, PathBuf) {
    tampered_copy_of("aead_v3", f)
}

fn tampered_copy_of(case: &str, f: impl FnOnce(&Path)) -> (tempfile::TempDir, PathBuf) {
    crate::encryption_tests::install();
    let tmp = tempfile::tempdir().unwrap();
    let path = tmp.path().join("t");
    copy_dir(&fixtures().join(case), &path);
    f(&path);
    (tmp, path)
}

#[test]
fn any_bit_flip_in_an_authenticated_chunk_is_never_served() {
    let size = std::fs::metadata(fixtures().join("aead_v3").join(chunk_path(&fixtures().join("aead_v3")).file_name().unwrap())).unwrap().len() as usize;
    let want = sorted(expected("aead_v3"));
    let (mut failed_in_data, mut data_positions) = (0, 0);
    for pos in 0..size {
        let (_d, path) = tampered_copy(|p| {
            let c = chunk_path(p);
            let mut b = std::fs::read(&c).unwrap();
            b[pos] ^= 1 << (pos % 8);
            fix_chunk_crcs(&mut b);
            std::fs::write(&c, b).unwrap();
        });
        let in_data = (96..size - 24).contains(&pos);
        match outcome(&path) {
            Err(moosedb_core::Error::Corrupt(_) | moosedb_core::Error::Crypto(_) | moosedb_core::Error::NotFound(_)) => {
                failed_in_data += usize::from(in_data);
            }
            Err(e) => panic!("byte {pos}: unexpected error {e}"),
            // Damage visible without the key (header, footer) quarantines the
            // chunk as before: rows go missing, but none is ever altered.
            Ok(rows) => assert!(rows.iter().all(|r| want.contains(r)), "byte {pos}: altered data was served"),
        }
        data_positions += usize::from(in_data);
    }
    assert_eq!(failed_in_data, data_positions, "every byte of blocks and index must be authenticated");
}

#[test]
fn blocks_cannot_be_swapped_between_chunks() {
    crate::encryption_tests::install();
    let tmp = tempfile::tempdir().unwrap();
    let make = |name: &str| {
        let p = tmp.path().join(name);
        let t = create_open(&p, opts(true));
        for i in 0..30 {
            t.write(row(i, "srv1", i as f64)).unwrap();
        }
        t.flush().unwrap();
        drop(t);
        p
    };
    let (a, b) = (make("a"), make("b"));
    let (mut ca, cb) = (std::fs::read(chunk_path(&a)).unwrap(), std::fs::read(chunk_path(&b)).unwrap());
    assert_eq!(ca.len(), cb.len());
    // Same logical content, so same layout: move the first blocks of B into A.
    ca[96..160].copy_from_slice(&cb[96..160]);
    assert_ne!(ca, std::fs::read(chunk_path(&a)).unwrap());
    fix_chunk_crcs(&mut ca);
    std::fs::write(chunk_path(&a), ca).unwrap();
    assert!(matches!(outcome(&a), Err(moosedb_core::Error::Corrupt(_))));
    assert_eq!(outcome(&b).unwrap().len(), 30);
}

#[test]
fn any_bit_flip_in_an_authenticated_wal_entry_is_refused() {
    let first = |p: &Path| {
        let w = std::fs::read(wal_path(p)).unwrap();
        let len = u32::from_le_bytes(w[40 + 4..40 + 8].try_into().unwrap()) as usize;
        (w, len)
    };
    let (_, len) = first(&fixtures().join("aead_v3"));
    for pos in 0..len {
        let (_d, path) = tampered_copy(|p| {
            let (mut w, len) = first(p);
            w[48 + pos] ^= 1 << (pos % 8);
            let c = crc(&w[44..48 + len]);
            w[40..44].copy_from_slice(&c);
            std::fs::write(wal_path(p), w).unwrap();
        });
        assert!(matches!(outcome(&path), Err(moosedb_core::Error::Crypto(_))), "WAL byte {pos} was accepted");
    }
}

#[test]
fn a_wal_segment_renamed_to_another_number_is_refused() {
    let (_d, path) = tampered_copy(|p| {
        let w = wal_path(p);
        std::fs::rename(&w, w.with_file_name("wal_000009.tfl.wal")).unwrap();
        // The MANIFEST asks for segments from 2 on: 9 is replayed in its place.
    });
    assert!(outcome(&path).is_err());
}

#[test]
#[ignore = "measures; run with --release -- --ignored --nocapture"]
fn cost_of_authentication() {
    use std::time::Instant;
    crate::encryption_tests::install();
    let n = 600_000i64;
    for (label, encrypted) in [("plain", false), ("encrypted", true)] {
        let tmp = tempfile::tempdir().unwrap();
        let t = create_open(&tmp.path().join("t"), opts(encrypted));
        let t0 = Instant::now();
        for i in 0..n {
            t.write(row(i % 80_000, &format!("srv{}", i % 50), i as f64)).unwrap();
        }
        t.sync_wal(true).unwrap();
        let wal = t0.elapsed();
        t.flush().unwrap();
        let flush = t0.elapsed() - wal;
        let bytes: u64 = t.chunks().unwrap().iter().map(|c| c.file_size).sum();
        let t1 = Instant::now();
        let rows = all_rows(&t).len();
        let scan = t1.elapsed();
        let (n, mb) = (n as f64, bytes as f64 / 1e6);
        println!(
            "{label:9} {rows} rows ({mb:.1} MB of chunk): WAL {:.0} rows/s, flush {:.2} M rows/s, cold scan {:.2} M rows/s",
            n / wal.as_secs_f64(),
            n / flush.as_secs_f64() / 1e6,
            n / scan.as_secs_f64() / 1e6
        );
    }
}

#[test]
fn a_plaintext_wal_segment_in_an_encrypted_table_is_refused() {
    crate::encryption_tests::install();
    let tmp = tempfile::tempdir().unwrap();
    let make = |name: &str, encrypted: bool| {
        let p = tmp.path().join(name);
        let t = create_open(&p, opts(encrypted));
        for i in 0..5 {
            t.write(row(i, "srv1", i as f64)).unwrap();
        }
        t.sync_wal(true).unwrap();
        drop(t); // rows stay only in the WAL
        p
    };
    let (enc, plain) = (make("enc", true), make("plain", false));
    let enc_wal = std::fs::read(wal_path(&enc)).unwrap();
    std::fs::write(wal_path(&enc), std::fs::read(wal_path(&plain)).unwrap()).unwrap();
    assert!(matches!(outcome(&enc), Err(moosedb_core::Error::InvalidArg(_) | moosedb_core::Error::Corrupt(_))));
    // The reverse is refused the same way as for chunks.
    std::fs::write(wal_path(&plain), enc_wal).unwrap();
    assert!(Table::open(config(&plain, opts(false))).is_err());
}

// --- Authenticated MANIFEST (v4, encrypted tables) --------------------------

fn manifest_path(dir: &Path) -> PathBuf {
    dir.join("MANIFEST")
}

fn sealed_table(tmp: &Path, name: &str) -> PathBuf {
    crate::encryption_tests::install();
    let path = tmp.join(name);
    let t = create_open(&path, opts(true));
    populate(&t);
    drop(t);
    path
}

/// A MANIFEST in the plain formats (what an attacker without the key can
/// write, checksum included): v2 without tombstones, or v3 with none.
fn plain_manifest(version: u16, wal_seq: u64, next: u64, replay: u64, chunks: &[u64]) -> Vec<u8> {
    let mut b = b"TFLM".to_vec();
    b.extend_from_slice(&version.to_le_bytes());
    b.extend_from_slice(&0u16.to_le_bytes());
    for v in [wal_seq, next, replay] {
        b.extend_from_slice(&v.to_le_bytes());
    }
    if version == 3 {
        b.extend_from_slice(&0u64.to_le_bytes()); // tseq
    }
    b.extend_from_slice(&(chunks.len() as u32).to_le_bytes());
    for id in chunks {
        b.extend_from_slice(&id.to_le_bytes());
        if version == 3 {
            b.extend_from_slice(&0u64.to_le_bytes());
        }
    }
    if version == 3 {
        b.extend_from_slice(&[0u8; 8]); // no range, no row tombstones
    }
    let c = crc(&b);
    b.extend_from_slice(&c);
    b
}

fn is_refusal(r: &Result<Vec<Row>, moosedb_core::Error>) -> bool {
    matches!(r, Err(moosedb_core::Error::Crypto(_) | moosedb_core::Error::Corrupt(_)))
}

#[test]
fn an_encrypted_table_writes_a_sealed_manifest_and_a_plain_one_stays_plain() {
    let tmp = tempfile::tempdir().unwrap();
    let enc = sealed_table(tmp.path(), "enc");
    let m = std::fs::read(manifest_path(&enc)).unwrap();
    assert_eq!(u16::from_le_bytes([m[4], m[5]]), 4);
    assert_eq!(outcome(&enc).unwrap().len(), 35);
    let plain = tmp.path().join("plain");
    drop(create_open(&plain, opts(false)));
    assert_eq!(u16::from_le_bytes(std::fs::read(manifest_path(&plain)).unwrap()[4..6].try_into().unwrap()), 2);
}

#[test]
fn any_bit_flip_in_the_sealed_manifest_is_refused() {
    let tmp = tempfile::tempdir().unwrap();
    let base = sealed_table(tmp.path(), "base");
    let size = std::fs::metadata(manifest_path(&base)).unwrap().len() as usize;
    for pos in 0..size {
        let copy = tmp.path().join(format!("flip{pos}"));
        copy_dir(&base, &copy);
        let mut b = std::fs::read(manifest_path(&copy)).unwrap();
        b[pos] ^= 1 << (pos % 8);
        std::fs::write(manifest_path(&copy), b).unwrap();
        let r = outcome(&copy);
        assert!(is_refusal(&r), "MANIFEST byte {pos}: {:?}", r.map(|r| r.len()));
        assert!(chunk_path(&copy).exists(), "MANIFEST byte {pos}: a chunk was deleted");
    }
    // Truncation and an empty file are errors too, never an empty table.
    for n in [0, 8, size / 2, size - 1] {
        let copy = tmp.path().join(format!("cut{n}"));
        copy_dir(&base, &copy);
        let b = std::fs::read(manifest_path(&copy)).unwrap();
        std::fs::write(manifest_path(&copy), &b[..n]).unwrap();
        assert!(is_refusal(&outcome(&copy)), "MANIFEST cut to {n}");
        assert!(chunk_path(&copy).exists());
    }
}

#[test]
fn a_plain_manifest_forged_over_a_sealed_table_is_refused_and_deletes_nothing() {
    let tmp = tempfile::tempdir().unwrap();
    let base = sealed_table(tmp.path(), "base");
    let forged = [
        ("chunk removed from the list", plain_manifest(2, 1, 2, 2, &[])),
        ("replay_seq and flush point rolled back", plain_manifest(2, 0, 1, 1, &[1])),
        ("tombstones dropped (v3)", plain_manifest(3, 1, 2, 2, &[1])),
    ];
    for (what, bytes) in forged {
        let copy = tmp.path().join("forged");
        let _ = std::fs::remove_dir_all(&copy);
        copy_dir(&base, &copy);
        std::fs::write(manifest_path(&copy), &bytes).unwrap();
        let r = outcome(&copy);
        assert!(matches!(r, Err(moosedb_core::Error::Crypto(_))), "{what}: {:?}", r.map(|r| r.len()));
        assert_eq!(std::fs::read(manifest_path(&copy)).unwrap(), bytes, "{what}: the MANIFEST was rewritten");
        assert!(chunk_path(&copy).exists(), "{what}: the chunk was deleted as an orphan");
    }
}

#[test]
fn a_chunk_copied_from_another_table_or_generation_with_the_same_key_is_refused() {
    let tmp = tempfile::tempdir().unwrap();
    let a = sealed_table(tmp.path(), "a");
    let b = sealed_table(tmp.path(), "b"); // same rows, same chunk id and file name, other IV
    let (ca, cb) = (chunk_path(&a), chunk_path(&b));
    assert_eq!(ca.file_name(), cb.file_name());
    let (own, foreign) = (std::fs::read(&ca).unwrap(), std::fs::read(&cb).unwrap());
    assert_ne!(own, foreign);
    std::fs::write(&ca, foreign).unwrap();
    let r = outcome(&a);
    assert!(matches!(r, Err(moosedb_core::Error::Crypto(_))), "{:?}", r.map(|r| r.len()));
    // The right file is accepted again.
    std::fs::write(&ca, own).unwrap();
    assert_eq!(outcome(&a).unwrap().len(), 35);
}

#[test]
fn a_chunk_damaged_in_an_authenticated_table_is_not_quarantined() {
    let tmp = tempfile::tempdir().unwrap();
    let base = sealed_table(tmp.path(), "base");
    let c = chunk_path(&base);
    let mut b = std::fs::read(&c).unwrap();
    let n = b.len();
    b[n - 1] ^= 1; // footer magic: damage provable without the key (the old quarantine case)
    std::fs::write(&c, &b).unwrap();
    assert!(is_refusal(&outcome(&base)));
    assert!(c.exists(), "the chunk must stay where it is");
    assert!(!std::fs::read_dir(&base).unwrap().any(|e| e.unwrap().file_name().to_string_lossy().ends_with(".corrupt")));
    // Renaming it to .corrupt is not a way to drop it from the list either.
    let mut aside = c.as_os_str().to_owned();
    aside.push(".corrupt");
    std::fs::rename(&c, &aside).unwrap();
    assert!(is_refusal(&outcome(&base)));
    damaged_chunk_recovery(tmp.path());
}

/// The opt-in `moosedb_recover_damaged_chunks` switch (process-wide, so this runs inside the
/// one test above, never in parallel with another that damages a chunk).
fn damaged_chunk_recovery(root: &Path) {
    let two = root.join("two");
    let t = create_open(&two, opts(true));
    for (from, to) in [(0, 10), (20, 30)] {
        for i in from..to {
            t.write(row(i, "a", i as f64)).unwrap();
        }
        t.flush().unwrap();
    }
    let mut files: Vec<PathBuf> = std::fs::read_dir(&two).unwrap().map(|e| e.unwrap().path()).filter(|p| p.extension().is_some_and(|x| x == "tfl")).collect();
    files.sort();
    assert_eq!(files.len(), 2);
    drop(t);
    let mut b = std::fs::read(&files[0]).unwrap();
    let n = b.len();
    b[n - 1] ^= 1;
    std::fs::write(&files[0], &b).unwrap();
    let before = std::fs::read(manifest_path(&two)).unwrap();

    // OFF (default): refuses, tells what to do, names no datadir path, deletes and rewrites nothing.
    let err = outcome(&two).unwrap_err();
    assert!(matches!(err, moosedb_core::Error::Crypto(_)), "{err}");
    let msg = err.to_string();
    assert!(msg.contains("moosedb_recover_damaged_chunks") && msg.contains("backup"), "{msg}");
    assert!(!msg.contains(root.to_str().unwrap()), "{msg}");
    assert_eq!(std::fs::read(manifest_path(&two)).unwrap(), before);
    assert!(files.iter().all(|f| f.exists()));

    // ON: the table opens without that chunk; the other one is intact and the MANIFEST sealed again.
    moosedb_core::settings::get().set_recover_damaged_chunks(true);
    let r = outcome(&two);
    moosedb_core::settings::get().set_recover_damaged_chunks(false);
    assert_eq!(sorted(r.unwrap()), sorted((20..30).map(|i| row(i, "a", i as f64)).collect()));
    let after = std::fs::read(manifest_path(&two)).unwrap();
    assert_ne!(after, before);
    assert_eq!(u16::from_le_bytes([after[4], after[5]]), 4);
    assert!(!files[0].exists() && files[1].exists());
    // OFF again: the repaired table opens normally.
    assert_eq!(outcome(&two).unwrap().len(), 10);
}

#[test]
fn a_stale_but_authentic_manifest_does_not_cost_the_newer_chunks() {
    crate::encryption_tests::install();
    let tmp = tempfile::tempdir().unwrap();
    let path = tmp.path().join("t");
    let t = create_open(&path, opts(true));
    for i in 0..10 {
        t.write(row(i, "a", i as f64)).unwrap();
    }
    t.flush().unwrap();
    let stale = std::fs::read(manifest_path(&path)).unwrap(); // lists chunk 1 only
    for i in 10..20 {
        t.write(row(i, "a", i as f64)).unwrap();
    }
    t.flush().unwrap();
    t.compact(i64::MIN, i64::MAX, base_ts()).unwrap(); // chunk 1 is gone, a merged chunk replaces it
    drop(t);
    let chunks = |p: &Path| {
        let mut v: Vec<String> = std::fs::read_dir(p).unwrap().map(|e| e.unwrap().file_name().to_string_lossy().into_owned()).filter(|n| n.ends_with(".tfl")).collect();
        v.sort();
        v
    };
    let before = chunks(&path);
    assert!(!before.is_empty());
    std::fs::write(manifest_path(&path), stale).unwrap();
    assert!(outcome(&path).is_err(), "the stale MANIFEST lists a chunk that no longer exists");
    assert_eq!(chunks(&path), before, "a refused open must not delete the chunks the stale MANIFEST does not list");
}

#[test]
fn an_uninspectable_file_blocks_the_plain_manifest_instead_of_counting_as_unmarked() {
    // ctr_v2 is a legacy table that migrates; a chunk-named file whose header cannot be read must stop it.
    for bad in ["short", "dir"] {
        let (_k, path) = tampered_copy_of("ctr_v2", |p| {
            let f = p.join("chunk_20261001T000000_20261002T000000_000009.tfl");
            if bad == "short" {
                std::fs::write(f, b"too short").unwrap();
            } else {
                std::fs::create_dir(f).unwrap();
            }
        });
        let before = std::fs::read(manifest_path(&path)).unwrap();
        let r = outcome(&path);
        assert!(matches!(r, Err(moosedb_core::Error::Crypto(_))), "{bad}: {:?}", r.map(|r| r.len()));
        assert_eq!(std::fs::read(manifest_path(&path)).unwrap(), before, "{bad}");
    }
}

#[test]
fn a_key_provider_failure_while_sealing_the_manifest_is_an_error_not_a_poisoned_table() {
    crate::encryption_tests::install();
    // Key lookups of one operation, in order: [compaction: rekey check,] new chunk, MANIFEST seal.
    // The WAL rotation after a flush is not swept: its failure poisons the table by design.
    for (op, k) in [("flush", 0), ("flush", 1), ("delete+flush", 0), ("delete+flush", 1), ("compact", 0), ("compact", 1), ("compact", 2)] {
        let tmp = tempfile::tempdir().unwrap();
        let path = tmp.path().join("t");
        let o = RawOptions { encryption_key_id: Some(77), ..Default::default() };
        let t = create_open(&path, o);
        for i in 0..10 {
            t.write(row(i, "a", i as f64)).unwrap();
        }
        if op == "compact" {
            t.flush().unwrap();
            for i in 10..20 {
                t.write(row(i, "a", i as f64)).unwrap();
            }
            t.flush().unwrap();
        }
        if op == "delete+flush" {
            t.delete_range(None, base_ts(), base_ts() + 3 * MICROS_PER_SEC - 1, None, true).unwrap();
        }
        let run = |t: &Table| match op {
            "compact" => t.compact(i64::MIN, i64::MAX, base_ts()).map(|_| ()),
            _ => t.flush(),
        };
        crate::encryption_tests::fail_key_77_at(k);
        let failed = run(&t);
        crate::encryption_tests::fail_key_77_at(-1);
        let Err(err) = failed else { continue }; // fewer lookups than k
        assert!(!matches!(err, moosedb_core::Error::ReadOnly(_)), "{op}/{k}: {err}");
        t.write(row(500, "a", 1.0)).unwrap_or_else(|e| panic!("{op}/{k}: table poisoned: {e}"));
        run(&t).unwrap_or_else(|e| panic!("{op}/{k}: retry failed: {e}"));
        let n = all_rows(&t).len();
        drop(t);
        let o = RawOptions { encryption_key_id: Some(77), ..Default::default() };
        assert_eq!(all_rows(&Table::open(config(&path, o)).unwrap()).len(), n, "{op}/{k}");
    }
}

/// Writes `legacy` over the MANIFEST of a fixture copy, opens (migrating),
/// and checks the downgrade door is shut afterwards.
fn migrates_and_cannot_be_downgraded(case: &str, legacy: Option<Vec<u8>>) {
    let (_keep, path) = tampered_copy_of(case, |p| {
        if let Some(b) = &legacy {
            std::fs::write(manifest_path(p), b).unwrap();
        }
    });
    let old = std::fs::read(manifest_path(&path)).unwrap();
    assert!(matches!(u16::from_le_bytes([old[4], old[5]]), 1..=3), "fixture MANIFEST must be a plain one");
    assert_eq!(sorted(outcome(&path).unwrap()), sorted(expected(case)));
    let sealed = std::fs::read(manifest_path(&path)).unwrap();
    assert_eq!(u16::from_le_bytes([sealed[4], sealed[5]]), 4, "{case}: migrated by the first open");
    assert_eq!(sorted(outcome(&path).unwrap()), sorted(expected(case)), "{case}: reopen");
    // An attacker puts the old MANIFEST back (with a valid checksum): refused.
    std::fs::write(manifest_path(&path), &old).unwrap();
    assert!(matches!(outcome(&path), Err(moosedb_core::Error::Crypto(_))), "{case}: downgrade accepted");
    assert_eq!(std::fs::read(manifest_path(&path)).unwrap(), old, "{case}: refusal must not rewrite");
}

#[test]
fn legacy_encrypted_manifests_are_read_migrated_and_cannot_be_put_back() {
    // v2 written by the format 1.0 code, with CTR chunks / with GCM chunks.
    migrates_and_cannot_be_downgraded("ctr_v2", None);
    migrates_and_cannot_be_downgraded("aead_v3", None);
    // An encrypted MANIFEST v3 (tombstone layout) from the 1.0 code: same chunk as ctr_v2.
    let m = std::fs::read(fixtures().join("ctr_v2").join("MANIFEST")).unwrap();
    let u = |at: usize| u64::from_le_bytes(m[at..at + 8].try_into().unwrap());
    migrates_and_cannot_be_downgraded("ctr_v2", Some(plain_manifest(3, u(8), u(16), u(24), &[1])));
}

// --- Zone maps (a section inside the index+Bloom unit, flag ZONES) -----------

#[test]
#[ignore = "writes fixtures with the current format"]
fn gen_fixture_zones() {
    generate("zones_v2", false);
    generate("zones_v3", true);
}

/// Scan with a value predicate that no chunk row meets, minus the rows the
/// predicate rejects: identical whether or not summaries exist.
fn pruned_equals_unpruned(t: &Table, case: &str) -> u64 {
    use moosedb_core::{prune_stats, ColPred, ScanFilter};
    let preds = [ColPred::Int { col: 4, lo: 4, hi: 6 }, ColPred::Int { col: 4, lo: 5_000, hi: 6_000 }];
    let before = prune_stats().entries_tested;
    for p in preds {
        let want = |f: &ScanFilter| -> Vec<Row> {
            let mut s = t.scan(f, false).unwrap();
            let mut out = Vec::new();
            while let Some((_, r)) = s.next_row().unwrap() {
                if let (ColPred::Int { lo, hi, .. }, moosedb_core::Value::Int(v)) = (&p, &r[4]) {
                    if lo <= v && v <= hi {
                        out.push(r);
                    }
                }
            }
            sorted(out)
        };
        let f = ScanFilter { cols: vec![p.clone()], ..ScanFilter::default() };
        assert_eq!(want(&f), want(&ScanFilter::default()), "{case}: {p:?}");
    }
    prune_stats().entries_tested - before
}

#[test]
fn chunks_without_zone_maps_are_read_and_never_pruned() {
    for (case, enc) in [("plain_v2", false), ("ctr_v2", true), ("aead_v3", true)] {
        let (_d, t) = check_case(case, enc);
        assert!(t.chunks().unwrap().iter().all(|c| c.zones.is_none()), "{case}");
        // no summaries: the value test is never even reached (modulo parallel tests)
        pruned_equals_unpruned(&t, case);
    }
}

#[test]
fn chunks_with_zone_maps_are_read_and_pruned() {
    for (case, enc, version) in [("zones_v2", false, 2), ("zones_v3", true, 3)] {
        let (_d, t) = check_case(case, enc);
        assert_eq!(chunk_versions(&t), vec![version], "{case}: summaries need no new version");
        assert!(t.chunks().unwrap().iter().all(|c| c.zones.is_some()), "{case}");
        assert!(pruned_equals_unpruned(&t, case) >= 2, "{case}: entries were tested");
    }
}

#[test]
fn any_bit_flip_in_the_sealed_zone_section_is_never_served() {
    let dir = fixtures().join("zones_v3");
    let name = chunk_path(&dir);
    let orig = std::fs::read(&name).unwrap();
    let want = sorted(expected("zones_v3"));
    let flag_zones = 1u16 << 3;
    assert_ne!(u16::from_le_bytes([orig[6], orig[7]]) & flag_zones, 0);
    // every byte from the first block to the footer: blocks, index, Bloom, summaries
    for pos in 96..orig.len() - 24 {
        let (_d, path) = tampered_copy_of("zones_v3", |p| {
            let c = chunk_path(p);
            let mut b = std::fs::read(&c).unwrap();
            b[pos] ^= 1 << (pos % 8);
            fix_chunk_crcs(&mut b);
            std::fs::write(&c, b).unwrap();
        });
        match outcome(&path) {
            Err(moosedb_core::Error::Corrupt(_) | moosedb_core::Error::Crypto(_) | moosedb_core::Error::NotFound(_)) => {}
            Err(e) => panic!("byte {pos}: unexpected error {e}"),
            Ok(rows) => panic!("byte {pos}: damaged chunk served {} rows (want {})", rows.len(), want.len()),
        }
    }
    // clearing the header flag (and fixing the header CRC) strips the summaries: the AAD notices
    let (_d, path) = tampered_copy_of("zones_v3", |p| {
        let c = chunk_path(p);
        let mut b = std::fs::read(&c).unwrap();
        b[6] &= !(1 << 3);
        fix_chunk_crcs(&mut b);
        std::fs::write(&c, b).unwrap();
    });
    assert!(matches!(outcome(&path), Err(moosedb_core::Error::Crypto(_))));
}

#[test]
fn a_damaged_plaintext_zone_section_is_ignored_not_trusted() {
    use moosedb_core::{ColPred, ScanFilter};
    let dir = fixtures().join("zones_v2");
    let orig = std::fs::read(chunk_path(&dir)).unwrap();
    let f = orig.len() - 24;
    let bloom_offset = u64::from_le_bytes(orig[f + 8..f + 16].try_into().unwrap()) as usize;
    let words = u32::from_le_bytes(orig[bloom_offset + 1..bloom_offset + 5].try_into().unwrap()) as usize;
    let zone_start = bloom_offset + 5 + 8 * words;
    assert!(zone_start < f, "a zone section follows the series Bloom");
    // the predicate matches row 4 only; a lying summary must not hide it
    let probe = ScanFilter { cols: vec![ColPred::Int { col: 4, lo: 4, hi: 4 }], ..ScanFilter::default() };
    for pos in zone_start..f {
        let tmp = tempfile::tempdir().unwrap();
        let path = tmp.path().join("t");
        copy_dir(&dir, &path);
        let c = chunk_path(&path);
        let mut b = std::fs::read(&c).unwrap();
        b[pos] ^= 1 << (pos % 8);
        fix_chunk_crcs(&mut b);
        std::fs::write(&c, b).unwrap();
        let t = Table::open(config(&path, opts(false))).unwrap();
        assert!(t.chunks().unwrap().iter().all(|c| c.zones.is_none()), "byte {pos}: summary kept");
        let mut s = t.scan(&probe, false).unwrap();
        let mut hit = false;
        while let Some((_, r)) = s.next_row().unwrap() {
            hit |= r[4] == moosedb_core::Value::Int(4);
        }
        assert!(hit, "byte {pos}: row hidden by a damaged summary");
    }
}
